"use strict";
function body(tag, explanation, keyPoints, visual, steps, formula, example, trap) {
  return {
    tag,
    explanation,
    keyPoints,
    visual,
    steps,
    ...formula ? { formula } : {},
    ...example ? { example } : {},
    ...trap ? { trap } : {}
  };
}
function cleanTopic(topic) {
  return topic.replace(/\u0060/g, "").replace(/^第[一二三四五六七八九十0-9]+章\s*/, "").replace(/^\d+(?:\.\d+)+\s*/, "").replace(/^\d+[.、]\s*/, "").replace(/[。；;]+$/g, "").replace(/\s+/g, " ").trim();
}
