function inferVisual(scope) {
  if (/概率|事件|样本|贝叶斯|全概率/.test(scope))
    return "probability";
  if (/分布|期望|方差|协方差|正态|统计/.test(scope))
    return "distribution";
  if (/梯度|方向导数/.test(scope))
    return "gradient";
  if (/向量|内积|数量积|向量积/.test(scope))
    return "vector";
  if (/平面|曲面|空间|极坐标/.test(scope))
    return "plane";
  if (/矩阵|行列式|特征值|二次型|线性相关|秩/.test(scope))
    return "matrix";
  if (/微分方程|常微分/.test(scope))
    return "ode";
  if (/级数|收敛半径|傅里叶/.test(scope))
    return "series";
  if (/积分|面积|体积|弧长/.test(scope))
    return "integral";
  if (/极值|单调|凹凸|拐点|渐近线/.test(scope))
    return "extremum";
  if (/导数|切线|微分/.test(scope))
    return "tangent";
  if (/连续|间断/.test(scope))
    return "continuity";
  if (/极限|无穷小|无穷大/.test(scope))
    return "limit";
  return "flow";
}
